contracts/AdminMultiSig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

contract AdminMultiSig is ReentrancyGuard {
    uint256 public constant MAX_OWNERS = 10;
    uint256 public constant MIN_REQUIRED = 2;
    
    uint256 private _transactionIds;
    
    address[] public owners;
    mapping(address => bool) public isOwner;
    uint256 public requiredSignatures;
    
    struct Transaction {
        uint256 id;
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint256 confirmations;
        uint256 timestamp;
        string description;
    }
    
    mapping(uint256 => Transaction) public transactions;
    mapping(uint256 => mapping(address => bool)) public confirmations;
    
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event RequirementChanged(uint256 required);
    
    event TransactionSubmitted(
        uint256 indexed transactionId,
        address indexed to,
        uint256 value,
        bytes data,
        string description
    );
    
    event TransactionConfirmed(
        uint256 indexed transactionId,
        address indexed owner
    );
    
    event TransactionRevoked(
        uint256 indexed transactionId,
        address indexed owner
    );
    
    event TransactionExecuted(
        uint256 indexed transactionId,
        address indexed to,
        uint256 value,
        bytes data
    );
    
    modifier onlyOwner() {
        require(isOwner[msg.sender], "AdminMultiSig: Not an owner");
        _;
    }
    
    modifier onlyWallet() {
        require(msg.sender == address(this), "AdminMultiSig: Not wallet");
        _;
    }
    
    modifier transactionExists(uint256 transactionId) {
        require(
            transactions[transactionId].to != address(0),
            "AdminMultiSig: Transaction does not exist"
        );
        _;
    }
    
    modifier notExecuted(uint256 transactionId) {
        require(
            !transactions[transactionId].executed,
            "AdminMultiSig: Transaction already executed"
        );
        _;
    }
    
    modifier notConfirmed(uint256 transactionId) {
        require(
            !confirmations[transactionId][msg.sender],
            "AdminMultiSig: Transaction already confirmed"
        );
        _;
    }
    
    constructor(address[] memory _owners, uint256 _requiredSignatures) {
        require(_owners.length > 0, "AdminMultiSig: Owners required");
        require(
            _requiredSignatures >= MIN_REQUIRED && 
            _requiredSignatures <= _owners.length,
            "AdminMultiSig: Invalid requirement"
        );
        require(_owners.length <= MAX_OWNERS, "AdminMultiSig: Too many owners");
        
        for (uint i = 0; i < _owners.length; i++) {
            address owner = _owners[i];
            require(owner != address(0), "AdminMultiSig: Invalid owner");
            require(!isOwner[owner], "AdminMultiSig: Duplicate owner");
            
            isOwner[owner] = true;
            owners.push(owner);
        }
        
        requiredSignatures = _requiredSignatures;
    }
    
    function submitTransaction(
        address to,
        uint256 value,
        bytes memory data,
        string memory description
    ) external onlyOwner returns (uint256) {
        require(to != address(0), "AdminMultiSig: Invalid destination");
        
        _transactionIds++;
        uint256 transactionId = _transactionIds;
        
        transactions[transactionId] = Transaction({
            id: transactionId,
            to: to,
            value: value,
            data: data,
            executed: false,
            confirmations: 0,
            timestamp: block.timestamp,
            description: description
        });
        
        emit TransactionSubmitted(transactionId, to, value, data, description);
        
        confirmTransaction(transactionId);
        
        return transactionId;
    }
    
    function confirmTransaction(uint256 transactionId)
        public
        onlyOwner
        transactionExists(transactionId)
        notExecuted(transactionId)
        notConfirmed(transactionId)
    {
        confirmations[transactionId][msg.sender] = true;
        transactions[transactionId].confirmations++;
        
        emit TransactionConfirmed(transactionId, msg.sender);
        
        if (isConfirmed(transactionId)) {
            executeTransaction(transactionId);
        }
    }
    
    function revokeConfirmation(uint256 transactionId)
        external
        onlyOwner
        transactionExists(transactionId)
        notExecuted(transactionId)
    {
        require(
            confirmations[transactionId][msg.sender],
            "AdminMultiSig: Transaction not confirmed"
        );
        
        confirmations[transactionId][msg.sender] = false;
        transactions[transactionId].confirmations--;
        
        emit TransactionRevoked(transactionId, msg.sender);
    }
    
    function executeTransaction(uint256 transactionId)
        public
        onlyOwner
        transactionExists(transactionId)
        notExecuted(transactionId)
        nonReentrant
    {
        require(isConfirmed(transactionId), "AdminMultiSig: Not enough confirmations");
        
        Transaction storage txn = transactions[transactionId];
        txn.executed = true;
        
        (bool success, ) = txn.to.call{value: txn.value}(txn.data);
        require(success, "AdminMultiSig: Transaction execution failed");
        
        emit TransactionExecuted(transactionId, txn.to, txn.value, txn.data);
    }
    
    function isConfirmed(uint256 transactionId) public view returns (bool) {
        return transactions[transactionId].confirmations >= requiredSignatures;
    }
    
    function getTransactionCount() external view returns (uint256) {
        return _transactionIds;
    }
    
    function getTransaction(uint256 transactionId)
        external
        view
        returns (Transaction memory)
    {
        return transactions[transactionId];
    }
    
    function getConfirmations(uint256 transactionId)
        external
        view
        returns (address[] memory)
    {
        address[] memory confirmationsArray = new address[](owners.length);
        uint256 count = 0;
        
        for (uint i = 0; i < owners.length; i++) {
            if (confirmations[transactionId][owners[i]]) {
                confirmationsArray[count] = owners[i];
                count++;
            }
        }
        
        address[] memory result = new address[](count);
        for (uint i = 0; i < count; i++) {
            result[i] = confirmationsArray[i];
        }
        
        return result;
    }
    
    function getTransactionsPaginated(uint256 offset, uint256 limit)
        external
        view
        returns (Transaction[] memory)
    {
        require(limit > 0 && limit <= 100, "AdminMultiSig: Invalid limit");
        
        uint256 totalCount = _transactionIds;
        if (offset >= totalCount) {
            return new Transaction[](0);
        }
        
        uint256 end = offset + limit;
        if (end > totalCount) {
            end = totalCount;
        }
        
        Transaction[] memory result = new Transaction[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            result[i - offset] = transactions[i + 1];
        }
        
        return result;
    }
    
    function getOwners() external view returns (address[] memory) {
        return owners;
    }
    
    function addOwner(address owner)
        external
        onlyWallet
    {
        require(owner != address(0), "AdminMultiSig: Invalid owner");
        require(!isOwner[owner], "AdminMultiSig: Owner exists");
        require(owners.length < MAX_OWNERS, "AdminMultiSig: Max owners reached");
        
        isOwner[owner] = true;
        owners.push(owner);
        
        emit OwnerAdded(owner);
    }
    
    function removeOwner(address owner)
        external
        onlyWallet
    {
        require(isOwner[owner], "AdminMultiSig: Not an owner");
        require(owners.length > requiredSignatures, "AdminMultiSig: Cannot remove owner");
        
        isOwner[owner] = false;
        
        for (uint i = 0; i < owners.length; i++) {
            if (owners[i] == owner) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                break;
            }
        }
        
        emit OwnerRemoved(owner);
    }
    
    function changeRequirement(uint256 _requiredSignatures)
        external
        onlyWallet
    {
        require(
            _requiredSignatures >= MIN_REQUIRED &&
            _requiredSignatures <= owners.length,
            "AdminMultiSig: Invalid requirement"
        );
        
        requiredSignatures = _requiredSignatures;
        
        emit RequirementChanged(_requiredSignatures);
    }
    
    receive() external payable {}
}

contracts/DonationContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

interface INodeRegistry {
    function registerNode(address operator, uint256 amount) external returns (uint256);
}

interface IERC8004 {
    function hasRole(bytes32 role, address account) external view returns (bool);
}

contract DonationContract is ReentrancyGuard, Ownable, Pausable {
    // Events
    event DonationReceived(address indexed donor, uint256 amount, string businessId, uint256 timestamp);
    event ValidatorFunded(uint256 indexed nodeId, uint256 amount, uint256 timestamp);
    event TaxReceiptRequested(address indexed donor, uint256 amount, string businessId);

    // State variables
    INodeRegistry public nodeRegistry;
    IERC8004 public identityRegistry;
    
    uint256 public constant VALIDATOR_COST = 2000 ether; // 2,000 AVAX
    uint256 public validatorPool;
    
    mapping(address => uint256) public donorBalances;
    mapping(address => string) public donorBusinessIds;

    constructor(address _nodeRegistry, address _identityRegistry) Ownable(msg.sender) {
        nodeRegistry = INodeRegistry(_nodeRegistry);
        identityRegistry = IERC8004(_identityRegistry);
    }

    /**
     * @dev Main donation function. Accepts AVAX and records the donation.
     * @param businessId The unique identifier for the business (for tax receipts).
     */
    function donate(string calldata businessId) external payable nonReentrant whenNotPaused {
        require(msg.value > 0, "Donation must be greater than 0");
        
        // Update balances
        donorBalances[msg.sender] += msg.value;
        donorBusinessIds[msg.sender] = businessId;
        validatorPool += msg.value;
        
        // Emit events
        emit DonationReceived(msg.sender, msg.value, businessId, block.timestamp);
        emit TaxReceiptRequested(msg.sender, msg.value, businessId);
        
        // Check if we can fund a new validator
        if (validatorPool >= VALIDATOR_COST) {
            _deployValidator();
        }
    }

    /**
     * @dev Internal function to deploy a validator when the pool is full.
     */
    function _deployValidator() internal {
        // In a real scenario, this would interact with the P-Chain or a liquid staking contract.
        // Here we mock it by calling our NodeRegistry.
        
        uint256 amountToDeploy = VALIDATOR_COST;
        validatorPool -= amountToDeploy;
        
        // Register the node (mock ID returned)
        uint256 nodeId = nodeRegistry.registerNode(address(this), amountToDeploy);
        
        emit ValidatorFunded(nodeId, amountToDeploy, block.timestamp);
    }

    // Admin functions
    function setNodeRegistry(address _nodeRegistry) external onlyOwner {
        nodeRegistry = INodeRegistry(_nodeRegistry);
    }

    function setIdentityRegistry(address _identityRegistry) external onlyOwner {
        identityRegistry = IERC8004(_identityRegistry);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
    
    function withdraw() external onlyOwner {
        (bool success, ) = payable(owner()).call{value: address(this).balance}("");
        require(success, "Transfer failed");
    }
}

contracts/DonationTracker.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract DonationTracker is ReentrancyGuard, Pausable, AccessControl {
    
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    
    uint256 private _donationIds;
    
    struct Donation {
        uint256 id;
        string donationId;
        address donor;
        address projectAddress;
        uint256 amount;
        uint256 timestamp;
        string projectName;
        string companyName;
        bool verified;
    }
    
    mapping(uint256 => Donation) public donations;
    mapping(string => uint256) public donationIdToIndex;
    mapping(address => uint256[]) public donorDonations;
    mapping(address => uint256) public projectTotalReceived;
    
    uint256 public totalDonationsTracked;
    uint256 public totalAmountTracked;
    
    event DonationRecorded(
        uint256 indexed id,
        string indexed donationId,
        address indexed donor,
        address projectAddress,
        uint256 amount,
        string projectName,
        string companyName
    );
    
    event DonationVerified(uint256 indexed id, string indexed donationId);
    event ProjectFunded(address indexed projectAddress, uint256 amount);
    
    constructor(address admin) {
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ADMIN_ROLE, admin);
        _grantRole(OPERATOR_ROLE, admin);
    }
    
    function recordDonation(
        string memory donationId,
        address donor,
        address projectAddress,
        uint256 amount,
        string memory projectName,
        string memory companyName
    ) external onlyRole(OPERATOR_ROLE) whenNotPaused nonReentrant {
        require(bytes(donationId).length > 0, "DonationTracker: Invalid donation ID");
        require(donor != address(0), "DonationTracker: Invalid donor address");
        require(projectAddress != address(0), "DonationTracker: Invalid project address");
        require(amount > 0, "DonationTracker: Amount must be greater than 0");
        require(donationIdToIndex[donationId] == 0, "DonationTracker: Donation already recorded");
        
        _donationIds++;
        uint256 newId = _donationIds;
        
        donations[newId] = Donation({
            id: newId,
            donationId: donationId,
            donor: donor,
            projectAddress: projectAddress,
            amount: amount,
            timestamp: block.timestamp,
            projectName: projectName,
            companyName: companyName,
            verified: false
        });
        
        donationIdToIndex[donationId] = newId;
        donorDonations[donor].push(newId);
        projectTotalReceived[projectAddress] += amount;
        
        totalDonationsTracked++;
        totalAmountTracked += amount;
        
        emit DonationRecorded(
            newId,
            donationId,
            donor,
            projectAddress,
            amount,
            projectName,
            companyName
        );
    }
    
    function verifyDonation(string memory donationId) 
        external 
        onlyRole(OPERATOR_ROLE) 
        whenNotPaused 
    {
        uint256 id = donationIdToIndex[donationId];
        require(id > 0, "DonationTracker: Donation not found");
        require(!donations[id].verified, "DonationTracker: Donation already verified");
        
        donations[id].verified = true;
        
        emit DonationVerified(id, donationId);
    }
    
    function getDonationById(string memory donationId) 
        external 
        view 
        returns (Donation memory) 
    {
        uint256 id = donationIdToIndex[donationId];
        require(id > 0, "DonationTracker: Donation not found");
        return donations[id];
    }
    
    function getDonationsByDonor(address donor) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return donorDonations[donor];
    }
    
    function getProjectTotal(address projectAddress) 
        external 
        view 
        returns (uint256) 
    {
        return projectTotalReceived[projectAddress];
    }
    
    function getTotalStats() 
        external 
        view 
        returns (uint256 totalDonations, uint256 totalAmount) 
    {
        return (totalDonationsTracked, totalAmountTracked);
    }
    
    function getDonationsPaginated(uint256 offset, uint256 limit) 
        external 
        view 
        returns (Donation[] memory) 
    {
        require(limit > 0 && limit <= 100, "DonationTracker: Invalid limit");
        
        uint256 totalCount = _donationIds;
        if (offset >= totalCount) {
            return new Donation[](0);
        }
        
        uint256 end = offset + limit;
        if (end > totalCount) {
            end = totalCount;
        }
        
        Donation[] memory result = new Donation[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            result[i - offset] = donations[i + 1];
        }
        
        return result;
    }
    
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }
    
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
    
    function grantOperatorRole(address account) external onlyRole(ADMIN_ROLE) {
        grantRole(OPERATOR_ROLE, account);
    }
    
    function revokeOperatorRole(address account) external onlyRole(ADMIN_ROLE) {
        revokeRole(OPERATOR_ROLE, account);
    }
    
    function supportsInterface(bytes4 interfaceId) 
        public 
        view 
        override(AccessControl) 
        returns (bool) 
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/MockERC8004.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";

contract MockERC8004 is AccessControl {
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    function grantRole(bytes32 role, address account) public override {
        super.grantRole(role, account);
    }

    // Helper to verify if an account has a role (matching interface)
    function hasRole(bytes32 role, address account) public view override returns (bool) {
        return super.hasRole(role, account);
    }
}

contracts/NodeRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";

contract NodeRegistry is Ownable {
    constructor() Ownable(msg.sender) {}
    struct ValidatorNode {
        uint256 id;
        address operator;
        uint256 stakeAmount;
        uint256 deployTime;
        bool isActive;
        uint256 totalRewards;
    }

    ValidatorNode[] public nodes;
    mapping(address => uint256[]) public operatorNodes;

    event NodeRegistered(uint256 indexed nodeId, address indexed operator, uint256 stakeAmount);
    event RewardsUpdated(uint256 indexed nodeId, uint256 newRewards);

    /**
     * @dev Registers a new validator node.
     * @param operator The address operating the node (usually DonationContract).
     * @param amount The amount staked.
     */
    function registerNode(address operator, uint256 amount) external returns (uint256) {
        uint256 nodeId = nodes.length;
        
        nodes.push(ValidatorNode({
            id: nodeId,
            operator: operator,
            stakeAmount: amount,
            deployTime: block.timestamp,
            isActive: true,
            totalRewards: 0
        }));
        
        operatorNodes[operator].push(nodeId);
        
        emit NodeRegistered(nodeId, operator, amount);
        
        return nodeId;
    }

    /**
     * @dev Updates the rewards for a specific node (mocking oracle data).
     */
    function updateRewards(uint256 nodeId, uint256 rewards) external onlyOwner {
        require(nodeId < nodes.length, "Invalid node ID");
        nodes[nodeId].totalRewards += rewards;
        emit RewardsUpdated(nodeId, nodes[nodeId].totalRewards);
    }

    function getNodeCount() external view returns (uint256) {
        return nodes.length;
    }

    function getNodesByOperator(address operator) external view returns (uint256[] memory) {
        return operatorNodes[operator];
    }
}

contracts/ProjectDistribution.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

contract ProjectDistribution is ReentrancyGuard, Pausable, AccessControl {
    using SafeERC20 for IERC20;
    
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant DISTRIBUTOR_ROLE = keccak256("DISTRIBUTOR_ROLE");
    
    uint256 private _distributionIds;
    
    IERC20 public immutable usdcToken;
    address public treasury;
    
    struct Project {
        string id;
        string name;
        address walletAddress;
        bool isActive;
        uint256 totalReceived;
        uint256 totalDistributed;
        uint256 pendingAmount;
    }
    
    struct Distribution {
        uint256 id;
        string projectId;
        address projectAddress;
        uint256 amount;
        uint256 timestamp;
        string reason;
        bool executed;
    }
    
    struct Milestone {
        string projectId;
        string title;
        uint256 targetAmount;
        uint256 achievedAmount;
        uint256 releaseAmount;
        bool completed;
        bool distributed;
    }
    
    mapping(string => Project) public projects;
    mapping(uint256 => Distribution) public distributions;
    mapping(string => Milestone[]) public projectMilestones;
    mapping(string => bool) public projectExists;
    
    string[] public projectIds;
    uint256 public totalProjectCount;
    uint256 public totalDistributed;
    uint256 public totalPending;
    
    event ProjectRegistered(
        string indexed projectId,
        string name,
        address indexed walletAddress
    );
    
    event FundsReceived(
        string indexed projectId,
        uint256 amount,
        address indexed from
    );
    
    event FundsDistributed(
        uint256 indexed distributionId,
        string indexed projectId,
        address indexed projectAddress,
        uint256 amount,
        string reason
    );
    
    event MilestoneCompleted(
        string indexed projectId,
        string title,
        uint256 releaseAmount
    );
    
    event ProjectDeactivated(string indexed projectId);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    
    constructor(
        address _usdcToken,
        address _treasury,
        address _admin
    ) {
        require(_usdcToken != address(0), "ProjectDistribution: Invalid USDC token");
        require(_treasury != address(0), "ProjectDistribution: Invalid treasury");
        require(_admin != address(0), "ProjectDistribution: Invalid admin");
        
        usdcToken = IERC20(_usdcToken);
        treasury = _treasury;
        
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);
        _grantRole(DISTRIBUTOR_ROLE, _admin);
    }
    
    function registerProject(
        string memory projectId,
        string memory name,
        address walletAddress
    ) external onlyRole(ADMIN_ROLE) {
        require(bytes(projectId).length > 0, "ProjectDistribution: Invalid project ID");
        require(bytes(name).length > 0, "ProjectDistribution: Invalid project name");
        require(walletAddress != address(0), "ProjectDistribution: Invalid wallet address");
        require(!projectExists[projectId], "ProjectDistribution: Project already exists");
        
        projects[projectId] = Project({
            id: projectId,
            name: name,
            walletAddress: walletAddress,
            isActive: true,
            totalReceived: 0,
            totalDistributed: 0,
            pendingAmount: 0
        });
        
        projectExists[projectId] = true;
        projectIds.push(projectId);
        totalProjectCount++;
        
        emit ProjectRegistered(projectId, name, walletAddress);
    }
    
    function receiveFunds(string memory projectId, uint256 amount) 
        external 
        onlyRole(DISTRIBUTOR_ROLE) 
        whenNotPaused 
    {
        require(projectExists[projectId], "ProjectDistribution: Project not found");
        require(amount > 0, "ProjectDistribution: Amount must be greater than 0");
        
        Project storage project = projects[projectId];
        require(project.isActive, "ProjectDistribution: Project is not active");
        
        project.totalReceived += amount;
        project.pendingAmount += amount;
        totalPending += amount;
        
        emit FundsReceived(projectId, amount, msg.sender);
        
        _checkAndProcessMilestones(projectId);
    }
    
    function distributeFunds(
        string memory projectId,
        uint256 amount,
        string memory reason
    ) external onlyRole(DISTRIBUTOR_ROLE) whenNotPaused nonReentrant {
        require(projectExists[projectId], "ProjectDistribution: Project not found");
        require(amount > 0, "ProjectDistribution: Amount must be greater than 0");
        
        Project storage project = projects[projectId];
        require(project.isActive, "ProjectDistribution: Project is not active");
        require(project.pendingAmount >= amount, "ProjectDistribution: Insufficient pending funds");
        
        uint256 contractBalance = usdcToken.balanceOf(address(this));
        require(contractBalance >= amount, "ProjectDistribution: Insufficient contract balance");
        
        _distributionIds++;
        uint256 distributionId = _distributionIds;
        
        distributions[distributionId] = Distribution({
            id: distributionId,
            projectId: projectId,
            projectAddress: project.walletAddress,
            amount: amount,
            timestamp: block.timestamp,
            reason: reason,
            executed: false
        });
        
        project.pendingAmount -= amount;
        project.totalDistributed += amount;
        totalPending -= amount;
        totalDistributed += amount;
        
        usdcToken.safeTransfer(project.walletAddress, amount);
        
        distributions[distributionId].executed = true;
        
        emit FundsDistributed(
            distributionId,
            projectId,
            project.walletAddress,
            amount,
            reason
        );
    }
    
    function addMilestone(
        string memory projectId,
        string memory title,
        uint256 targetAmount,
        uint256 releaseAmount
    ) external onlyRole(ADMIN_ROLE) {
        require(projectExists[projectId], "ProjectDistribution: Project not found");
        require(targetAmount > 0, "ProjectDistribution: Target amount must be greater than 0");
        require(releaseAmount > 0, "ProjectDistribution: Release amount must be greater than 0");
        
        projectMilestones[projectId].push(Milestone({
            projectId: projectId,
            title: title,
            targetAmount: targetAmount,
            achievedAmount: 0,
            releaseAmount: releaseAmount,
            completed: false,
            distributed: false
        }));
    }
    
    function _checkAndProcessMilestones(string memory projectId) internal {
        Milestone[] storage milestones = projectMilestones[projectId];
        Project storage project = projects[projectId];
        
        for (uint i = 0; i < milestones.length; i++) {
            Milestone storage milestone = milestones[i];
            
            if (!milestone.completed && 
                project.totalReceived >= milestone.targetAmount) {
                milestone.completed = true;
                milestone.achievedAmount = project.totalReceived;
                
                emit MilestoneCompleted(
                    projectId,
                    milestone.title,
                    milestone.releaseAmount
                );
                
                if (!milestone.distributed && project.pendingAmount >= milestone.releaseAmount) {
                    _autoDistribute(projectId, milestone.releaseAmount, 
                        string(abi.encodePacked("Milestone: ", milestone.title)));
                    milestone.distributed = true;
                }
            }
        }
    }
    
    function _autoDistribute(
        string memory projectId,
        uint256 amount,
        string memory reason
    ) internal {
        Project storage project = projects[projectId];
        uint256 contractBalance = usdcToken.balanceOf(address(this));
        
        if (contractBalance >= amount && project.pendingAmount >= amount) {
            _distributionIds++;
            uint256 distributionId = _distributionIds;
            
            distributions[distributionId] = Distribution({
                id: distributionId,
                projectId: projectId,
                projectAddress: project.walletAddress,
                amount: amount,
                timestamp: block.timestamp,
                reason: reason,
                executed: true
            });
            
            project.pendingAmount -= amount;
            project.totalDistributed += amount;
            totalPending -= amount;
            totalDistributed += amount;
            
            usdcToken.safeTransfer(project.walletAddress, amount);
            
            emit FundsDistributed(
                distributionId,
                projectId,
                project.walletAddress,
                amount,
                reason
            );
        }
    }
    
    function getProjectDetails(string memory projectId) 
        external 
        view 
        returns (Project memory) 
    {
        require(projectExists[projectId], "ProjectDistribution: Project not found");
        return projects[projectId];
    }
    
    function getProjectMilestones(string memory projectId) 
        external 
        view 
        returns (Milestone[] memory) 
    {
        return projectMilestones[projectId];
    }
    
    function getAllProjects() external view returns (string[] memory) {
        return projectIds;
    }
    
    function deactivateProject(string memory projectId) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        require(projectExists[projectId], "ProjectDistribution: Project not found");
        projects[projectId].isActive = false;
        emit ProjectDeactivated(projectId);
    }
    
    function updateTreasury(address newTreasury) 
        external 
        onlyRole(ADMIN_ROLE) 
    {
        require(newTreasury != address(0), "ProjectDistribution: Invalid treasury");
        address oldTreasury = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(oldTreasury, newTreasury);
    }
    
    function emergencyWithdraw(address to, uint256 amount) 
        external 
        onlyRole(DEFAULT_ADMIN_ROLE) 
        nonReentrant 
    {
        require(to != address(0), "ProjectDistribution: Invalid recipient");
        uint256 balance = usdcToken.balanceOf(address(this));
        require(balance >= amount, "ProjectDistribution: Insufficient balance");
        
        usdcToken.safeTransfer(to, amount);
    }
    
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }
    
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }
    
    function supportsInterface(bytes4 interfaceId) 
        public 
        view 
        override(AccessControl) 
        returns (bool) 
    {
        return super.supportsInterface(interfaceId);
    }
}

